
public class SwaptwoNumberswithoutthirdVaribel {

	public static void main(String[] args){
		
		
		// TODO Auto-generated constructor stub
		
		int a =10;
		int b = 99;
		
		a=a+b;
		b=a-b;
		a=a-b;
		
		System.out.println("Swapped Number :" + a);
		System.out.println("Swapped Number :" + b);
	}

}
